import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as r,a as l}from"./chunks/M-S-N2.DstR7-iA.js";import{_ as c,o as p,c as d,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Caricamento nel Cloud","description":"","frontmatter":{"source_hash":"5577d64214","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/cloud.md","filePath":"it/use/cloud.md"}'),u={name:"it/use/cloud.md"};function g(h,t,v,b,f,z){return p(),d("div",null,[...t[0]||(t[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Caricamento nel Cloud</p></div><p>Il caricamento nel cloud ti permette di caricare la tua glicemia su vari servizi cloud o database.<br> Puoi usarlo per condividere i dati con dispositivi diversi da xDrip e per i report.</p><h3 id="nightscout-sync-rest-api" tabindex="-1">API Upload (REST) <a class="header-anchor" href="#nightscout-sync-rest-api" aria-label="Permalink to &quot;API Upload (REST) {#nightscout-sync-rest-api}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">API Upload (REST)</p><p> REST API è il modo standard per connettersi a Nightscout</p></div><p><a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> è il metodo universale per condividere i tuoi valori di glicemia, creare report e molto altro...</p><p>Dopo aver creato il tuo sito Nightscout, attiva la sincronizzazione per caricare i dati da xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Abilitato<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> REST API è il modo standard per connettersi a Nightscout</p></div><p>Se vuoi usare Nightscout per condividere la tua glicemia, assicurati che questa opzione sia attiva se usi un telefono con SIM e piano dati. Altrimenti il caricamento avverrà solo quando sei connesso a una rete Wi-Fi, il che va bene se usi Nightscout per raccogliere dati per i report.</p><div class="admonition xdripitem"><p class="admonition-title">Utilizza rete dati mobile<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Upload anche con rete dati mobile</p></div><p>Se usi filtri o plugin di calibrazione, puoi selezionare questa opzione per inviare a Nightscout i dati così come vengono mostrati da xDrip invece dei dati non calibrati/non filtrati.</p><div class="admonition xdripitem"><p class="admonition-title">Invia Glicemia Visualizzata<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Usa filtraggio del rumore e plugins (se abilitati) per il valore trasmesso</p></div><p>L&#39;URL di base è composto dal tuo API_SECRET (o da un token) e dall&#39;URL del tuo sito.<br> L&#39;esempio fornito nella finestra di dialogo era per un Nightscout basato su Azure.</p><div class="admonition xdripitem"><p class="admonition-title">URL di base</p><p> Formato: <a href="https://password@hostname/api/v1/" target="_blank" rel="noreferrer">https://password@hostname/api/v1/</a></p></div><p>Il formato dell&#39;URL deve essere come questo:</p><p><strong><code>https://your-API_SECRET@your-site.domain.fqd/api/v1/</code></strong></p><p>Trovi l&#39;API_SECRET nelle <a href="https://nightscout.github.io/nightscout/setup_variables/#nightscout-configuration" target="_blank" rel="noreferrer">variabili</a> del tuo Nightscout.</p><p>In alternativa puoi usare un <a href="https://nightscout.github.io/nightscout/security/#create-authentication-tokens-for-users" target="_blank" rel="noreferrer">token</a> admin per l&#39;autenticazione; in quel caso sarà così:</p><p><strong><code>https://xdrip-12ab34cd5678ef90@your-site.domain.fqd/api/v1/</code></strong></p><p>Se usi un servizio in hosting, contatta il fornitore.</p><div class="info custom-block"><p class="custom-block-title">Più siti</p><p>Se hai più di un sito Nightscout, xDrip può caricare su più URL Nightscout <strong>separati da spazi</strong>.<br><em><strong>Sugli URL secondari vengono caricati solo i valori di glicemia, non i trattamenti</strong></em></p></div><p>Se hai più dispositivi che caricano su Nightscout (sconsigliato) potresti voler scaricare anche i trattamenti da Nightscout per vedere le informazioni caricate dagli altri.</p><div class="admonition xdripitem"><p class="admonition-title">Scarica dati<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Prova anche a scaricare i dati da Nightscout</p></div><div class="warning custom-block"><p class="custom-block-title">Calibrazione automatica</p><p>È la stessa impostazione <a href="./../calibrate/advancedcal.html#use-treatment-bg-values">Calibrazione automatica</a> delle calibrazioni. Usala con cautela.</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibrazione automatica<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Calibra automaticamente utilizzando le letture di glicemia se le condizioni sembrano giuste, senza chiedere conferma (sperimentale)</p></div><br><div class="admonition xdripitem"><p class="admonition-title">Altre opzioni</p></div><p>Se il tuo Nightscout è disponibile solo su un server locale (su un IP privato), non tentare di caricare dati su Nightscout quando non sei a casa. Ignora questa opzione per un Nightscout nel cloud.</p><div class="admonition xdripitem"><p class="admonition-title">Salta upload LAN<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Per server locali con indirizzi 192.168.x.x, non caricare dati in assenza di connessione di rete locale.</p></div><p>Puoi caricare il livello della batteria del bridge o del sensore (se supportato).</p><div class="admonition xdripitem"><p class="admonition-title">Upload livello batteria del bridge<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Invia il livello della batteria a Nightscout. Deseleziona se il sensore di batteria non funziona.</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica il livello di batteria del trasmettitore OB1 G5/G6<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Invia le statistiche della batteria del trasmettitore Dexcom a Nightscout. Include tutti i dati mostrati sulla schermata Stato del Collector.</p></div><p>Puoi caricare i <a href="./mainUI.html#treatments">trattamenti</a> inseriti localmente nel <a href="https://nightscout.github.io/nightscout/setup_variables/#careportal-careportal" target="_blank" rel="noreferrer">Care Portal</a> di Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Carica trattamenti<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Invia i trattamenti a Nightscout. Deseleziona se il tuo careportal non funziona.</p></div><p>Puoi impostare un avviso quando il caricamento non riesce e aggiungere altre informazioni ai dati di glicemia caricati.</p><div class="admonition xdripitem"><p class="admonition-title">Allarmi in caso di errori<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Notifica e suona se il caricamento a Nightscout fallisce.</p></div><div class="admonition xdripitem"><p class="admonition-title">Aggiungi informazioni sulla sorgente dati al nome del dispositivo<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Per G5, invia il tipo di collector (es. OB1) e leggi lo stato di ricupero dati storici (per nativo) a Nightscout.</p></div><h5 id="backfill-data-to-nightscout" tabindex="-1">Recuperare i dati storici su Nightscout <a class="header-anchor" href="#backfill-data-to-nightscout" aria-label="Permalink to &quot;Recuperare i dati storici su Nightscout {#backfill-data-to-nightscout}&quot;">​</a></h5><p>Se hai creato da poco un sito Nightscout e vuoi caricare i tuoi dati storici dal database di xDrip, puoi usare il recupero dei dati storici.</p><div class="admonition xdripitem"><p class="admonition-title">Ricupera dati storici</p><p> Invia le letture di glicemia per lo storico</p></div><p>Seleziona il primo giorno del periodo che vuoi caricare (fino a oggi) e tocca <strong>DO IT!</strong><br> A seconda della quantità di dati e della velocità della rete, il caricamento può richiedere moltissimo tempo (ore).</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Nightscout Backfill</p><p>Choose the date for the oldest record to send to Nightscout. Use with care!</p><div style="background-color:gray;color:white;text-align:center;">  FEBRUARY 12, 2022 11:29PM </div><p><span style="background-color:gray;color:white;text-align:center;">  DO IT! </span> CANCEL</p></div><h3 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB {#mongodb}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Questo metodo è deprecato per Nightscout.</p></div><p>Puoi caricare direttamente la glicemia e lo stato del dispositivo in un database Mongo.</p><div class="admonition xdripitem"><p class="admonition-title">MongoDB</p><p> Upload diretto nel database, sconsigliato per Nightscout</p></div><p>Il caricamento su MongoDB è deprecato da quando mLab è stata acquisita da MongoDB e molti sono migrati su Atlas: <strong>non puoi usare un URI DNS seed <code>mongodb+srv</code></strong>.<br> Usa questa funzione solo se gestisci un tuo database <a href="https://github.com/mongodb/mongo" target="_blank" rel="noreferrer">Mongo</a>; la porta predefinita è 27017.</p><p>La struttura della <a href="https://www.mongodb.com/docs/manual/reference/connection-string/#connection-string-uri-format" target="_blank" rel="noreferrer">stringa di connessione URI</a> è:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb://databaseusername:databasepassword@your.mongo.url/databasename</span></span></code></pre></div><p>Per mantenere il database compatibile con Nightscout, non cambiare il nome della Collection né il nome della collection Device status rispetto ai valori predefiniti (se li cambi dovrai modificare anche le variabili corrispondenti in Nightscout, <code>MONGODB_COLLECTION</code> e <code>MONGO_DEVICESTATUS_COLLECTION</code>).</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>I dati caricati potrebbero non comparire nella pagina web di Nightscout, ma solo nei report di Nightscout.</p></div><h3 id="influxdb" tabindex="-1">InfluxDB <a class="header-anchor" href="#influxdb" aria-label="Permalink to &quot;InfluxDB {#influxdb}&quot;">​</a></h3><p>Puoi anche caricare i dati su un <a href="https://www.influxdata.com/products/influxdb-overview/" target="_blank" rel="noreferrer">InfluxDB</a> e usare Grafana per presentarli.</p><div class="admonition xdripitem"><p class="admonition-title">InfluxDB</p><p> Se usi un database privato InfluxDB, questo dovrebbe essere abilitato</p></div><p>Attenzione: l&#39;URI del tuo InfluxDB sarà espresso così:</p><p><code>https://host_address:port</code>, ad esempio per un server locale: <code>https://192.168.0.56:8086</code></p><h3 id="dex-share" tabindex="-1">Dex Share <a class="header-anchor" href="#dex-share" aria-label="Permalink to &quot;Dex Share {#dex-share}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Il nome utente non può essere un numero di telefono</p><p>Dovresti creare un <a href="https://www.dexcom.com/faqs/how-do-i-create-a-dependent-account" target="_blank" rel="noreferrer">account dipendente</a> per avere un nome utente solo testuale.<br> Dopo aver creato il nuovo account dipendente, assicurati di aver effettuato l&#39;accesso con questo account nelle app Dexcom e ricrea tutti i follower.</p></div><p>Quando hai un follower attivo, creato dalle app Dexcom, puoi usare xDrip per caricare su Dexcom Share.</p><div class="admonition xdripitem"><p class="admonition-title">Upload in Dexcom Share Server</p><p> Carica i dati nel server Dexcom in modo da poter utilizzare i dati con le applicazioni Dexcom</p></div><div class="info custom-block"><p class="custom-block-title">Info</p><p>Puoi caricare la tua glicemia su Dexcom Share, <strong>non su Dexcom Clarity</strong>.</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica valori di glicemia in Dexcom Share<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Abilitare per caricare sui server Dexcom</p></div><p>Se usi un account USA attiva questa opzione, <strong>per qualsiasi altro paese lasciala disattivata</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Account Dexcom basato negli USA<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Abilitare = l&#39;account e l&#39;app follower sono negli dagli Stati Uniti</p></div><p>Inserisci le credenziali che usi per accedere a Clarity.</p><div class="admonition xdripitem"><p class="admonition-title">Login account Dexcom</p><p> Il tuo login per il sito web di Dexcom</p></div><div class="admonition xdripitem"><p class="admonition-title">Password dell&#39;account Dexcom</p><p> La tua password per il sito Web di Dexcom</p></div><h3 id="tidepool" tabindex="-1">Tidepool <a class="header-anchor" href="#tidepool" aria-label="Permalink to &quot;Tidepool {#tidepool}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Tidepool</p><p> Carica i dati in Tidepool</p></div><p>Se hai un account <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a>, puoi caricare automaticamente i tuoi dati e condividerli con il tuo diabetologo.<br> Se xDrip può mostrare le <a href="./display.html#basal-information">informazioni sulla basale da uno stato esterno</a>, verranno caricate anche su Tidepool.</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizza con Tidepool<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Inserisci il tuo indirizzo email e la password (quelli che hai usato per la <a href="https://app.tidepool.org/signup/personal" target="_blank" rel="noreferrer">registrazione</a>).</p><div class="admonition xdripitem"><p class="admonition-title">Nome utente</p><p>Il tuo nome utente per l&#39;accesso a Tidepool, generalmente il tuo indirizzo email</p></div><div class="admonition xdripitem"><p class="admonition-title">Password</p><p>La tua password di Tidepool</p></div><p>Al termine, verifica la connessione.</p><div class="admonition xdripitem"><p class="admonition-title">Test di accesso a Tidepool</p></div><p>Tidepool non ha bisogno di dati in tempo reale: seleziona con il cursore il periodo dopo il quale i dati vengono caricati. Il valore predefinito è 15 minuti.</p><div class="admonition xdripitem"><p class="admonition-title">Età dei dati min (15)</p></div><p><strong>NON</strong> usare i server di test (lascia l&#39;opzione non selezionata).</p><div class="admonition xdripitem"><p class="admonition-title">Usa server di integrazione (test) - non utilizzare<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Puoi scegliere di caricare solo in determinate condizioni, per risparmiare batteria e costi dei dati.</p><div class="admonition xdripitem"><p class="admonition-title">Solo durante la carica<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Carica i dati solo durante la ricarica</p></div><div class="admonition xdripitem"><p class="admonition-title">Solo su WiFi<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Carica i dati solo quando connesso a una rete non contabilizzata, come Wifi</p></div><p>Se carichi anche manualmente i dati dal microinfusore, potresti voler disattivare il caricamento dei trattamenti di xDrip per evitare duplicati.</p><div class="admonition xdripitem"><p class="admonition-title">Non caricare i trattamenti<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Carica solo i dati CGM per evitare duplicati con il caricamento manuale dal micro</p></div><h5 id="web-deposit" tabindex="-1">Web Deposit <a class="header-anchor" href="#web-deposit" aria-label="Permalink to &quot;Web Deposit {#web-deposit}&quot;">​</a></h5><p>Web Deposit è una semplice API di caricamento in blocco usata attualmente per la diagnostica. È nascosta dietro la modalità Engineering e non è pensata per l&#39;uso normale.</p><h3 id="nightlite" tabindex="-1">NightLite <a class="header-anchor" href="#nightlite" aria-label="Permalink to &quot;NightLite {#nightlite}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">NightLite</p><p> Lightweight Nightscout compatible service intended for followers</p></div><p>NightLite è un servizio follower leggero e compatibile con Nightscout, un&#39;alternativa più semplice alla gestione di un tuo sito Nightscout se ti serve solo condividere la glicemia con i follower.</p><p>Vedi <a href="./nightlite.html">Configurazione del follower NightLite</a> per la sequenza di installazione completa.</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service</p></div><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard<br>  This contains your security key - do not disclose it</p></div><p>Una volta attivato, puoi mostrare un codice QR con i dati di connessione NightLite da far scansionare ai follower.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Codice QR</p></div><h3 id="nocturne" tabindex="-1">Nocturne <a class="header-anchor" href="#nocturne" aria-label="Permalink to &quot;Nocturne {#nocturne}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Nocturne</p><p> Carica su Nocturne API V4</p></div><p><a href="https://getnocturne.dev/" target="_blank" rel="noreferrer">Nocturne</a> è il successore moderno di Nightscout sviluppato dalla Nightscout Foundation. Se gestisci una tua istanza Nocturne, xDrip può caricare i dati direttamente su di essa.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita caricamento Nocturne<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>Inserisci l&#39;indirizzo della tua istanza Nocturne.</p><div class="admonition xdripitem"><p class="admonition-title">URL istanza Nocturne</p><p> Inserisci l&#39;URL della tua istanza Nocturne (es. <a href="https://mynocturne.example.com" target="_blank" rel="noreferrer">https://mynocturne.example.com</a>)</p></div><p>Poi autorizza xDrip con la tua istanza. In xDrip non viene memorizzata alcuna password: viene mostrato un codice, che inserisci nella pagina di approvazione della tua istanza Nocturne nel browser per completare la connessione.</p><div class="admonition xdripitem"><p class="admonition-title">Connetti a Nocturne</p><p> Autorizza xDrip+ con la tua istanza Nocturne</p></div><h4 id="quick-connect-from-nocturne" tabindex="-1">Quick Connect da Nocturne <a class="header-anchor" href="#quick-connect-from-nocturne" aria-label="Permalink to &quot;Quick Connect da Nocturne {#quick-connect-from-nocturne}&quot;">​</a></h4><p>Invece di digitare l&#39;URL dell&#39;istanza, lascia che sia Nocturne a configurare xDrip per te. Nella tua istanza Nocturne apri Connectors &amp; Apps, poi Set Up an Uploader, e seleziona xDrip+ nell&#39;elenco CGM Apps.</p><img src="'+r+'" style="zoom:75%;"><p>La pagina Set up xDrip+ mostra un codice QR Quick Connect.</p><img src="'+l+'" style="zoom:60%;"><div class="warning custom-block"><p class="custom-block-title">Scansiona questo codice QR con l&#39;app fotocamera del telefono, non con xDrip</p><p>Il codice QR Quick Connect è un link che apre xDrip sul telefono direttamente nella configurazione del connettore Nocturne. Scansionarlo con l&#39;importatore di impostazioni <a href="./copysettings.html#auto-configure">Configurazione automatica</a> di xDrip non funziona.</p></div><p>xDrip mostra poi un codice di autorizzazione. Inseriscilo nel campo Enter Authorization Code della stessa pagina Nocturne e tocca Continue per completare la connessione.</p><h4 id="alternate-method-settings-qr-code" tabindex="-1">Metodo alternativo: codice QR delle impostazioni <a class="header-anchor" href="#alternate-method-settings-qr-code" aria-label="Permalink to &quot;Metodo alternativo: codice QR delle impostazioni {#alternate-method-settings-qr-code}&quot;">​</a></h4><p>Se preferisci preparare tu stesso le impostazioni Nocturne, usa il configuratore qui sotto. Inserisci l&#39;URL della tua istanza, scegli cosa caricare, poi scansiona il codice QR generato dall&#39;interno di xDrip con <a href="./copysettings.html#auto-configure">Configurazione automatica</a> (Camera, oppure File immagine con il PNG scaricato). xDrip elenca le impostazioni e chiede conferma prima di applicarle.</p><div class="info custom-block"><p class="custom-block-title">A differenza del codice QR Quick Connect qui sopra, questo deve essere scansionato con xDrip, non con l&#39;app fotocamera.</p></div><p>Una volta importate le impostazioni, apri Impostazioni, Caricamento nel Cloud, Nocturne, tocca Connetti a Nocturne e inserisci nella tua istanza Nocturne il codice di autorizzazione mostrato da xDrip. I token di autorizzazione non fanno mai parte del codice QR.</p><iframe src="../../use/nocturne-qr.html" title="xDrip+ Nocturne QR configurator" style="width:100%;height:800px;border:1px solid #d9dee5;border-radius:8px;background:#f6f7f9;" loading="lazy"></iframe><p>Puoi anche <a href="../../use/nocturne-qr.html" target="_blank">aprire il configuratore in una pagina separata</a>.</p><p>Seleziona quali dati caricare. Le letture di glicemia sono attivate per impostazione predefinita; tutto il resto è facoltativo.</p><div class="admonition xdripitem"><p class="admonition-title">Carica glicemia<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Carica i valori di glucosio del sensore CGM</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica trattamenti<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica boli, CHO, note ed eventi del dispositivo</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica calibrazioni<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica le calibrazioni del sensore</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica misure capillare<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica le letture del glucometro</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica battito cardiaco<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica i dati del battito cardiaco</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica conteggio passi<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica i dati del conteggio passi</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica stato dispositivo<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica il livello della batteria del telefono e lo stato di carica</p></div><div class="admonition xdripitem"><p class="admonition-title">Carica monitoraggio movimento<span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Carica le classificazioni di attività riconosciute</p></div><div class="admonition xdripitem"><p class="admonition-title">Utilizza rete dati mobile<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Consenti upload su dati mobili</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',127)])])}const S=c(u,[["render",g]]);export{q as __pageData,S as default};
